{"code": "export async function main(input: unknown) {
  const res = await sdk.sentry.listIssues({ project: "jobs" });
  const targets = res.issues.filter(i => i.status === "unresolved");
  const out: Record<string, unknown> = {};
  for (const t of targets) {
    const s = await sdk.linear.searchIssues({ query: t.shortId });
    out[t.shortId] = s.issues;
  }
  return out;
}"}

{"code": "export async function main(input: unknown) {
  const res = await sdk.sentry.listIssues({ project: "jobs" });
  const targets = res.issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const plan = targets.map(t => ({ shortId: t.shortId, title: `[Sentry] ${t.shortId}`, description: t.culprit }));
  const created: any[] = [];
  for (const p of plan) {
    const c = await sdk.linear.createIssue({ title: p.title, description: p.description });
    created.push(c);
  }
  return { count: plan.length, plan, created };
}"}

